#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/irq_offload.h>
#include <zephyr/sys/slist.h>
#include <zephyr/init.h>
#include <zephyr/sys/printk.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

/*
 * The test uses 4 threads:
 * - Cooperative high priority
 * - Cooperative low priority
 * - Preemptible high priority
 * - Preemptible low priority
 */
#define COOP_HIGH_PRIORITY K_PRIO_COOP(1)
#define COOP_LOW_PRIORITY K_PRIO_COOP(2)
#define TASK_HIGH_PRIORITY K_PRIO_PREEMPT(1)
#define TASK_LOW_PRIORITY K_PRIO_PREEMPT(2)

enum fifo_test_state {
    FIFO_TEST_START,
    FIFO_TEST_GOT_ITEM,
    FIFO_TEST_DONE,
};

K_FIFO_DEFINE(test_fifo);

struct k_thread coop_high_thread;
struct k_thread coop_low_thread;
struct k_thread task_high_thread;
struct k_thread task_low_thread;

K_THREAD_STACK_DEFINE(coop_high_stack, STACK_SIZE);
K_THREAD_STACK_DEFINE(coop_low_stack, STACK_SIZE);
K_THREAD_STACK_DEFINE(task_high_stack, STACK_SIZE);
K_THREAD_STACK_DEFINE(task_low_stack, STACK_SIZE);

volatile enum fifo_test_state coop_high_state;
volatile enum fifo_test_state coop_low_state;
volatile enum fifo_test_state task_high_state;
volatile enum fifo_test_state task_low_state;

struct dummy_item {
    sys_snode_t node;
    int id;
};

void coop_high_entry(void *p1, void *p2, void *p3) {
    ARG_UNUSED(p1); ARG_UNUSED(p2); ARG_UNUSED(p3);
    struct dummy_item *item = k_fifo_get(&test_fifo, K_FOREVER);
    if (item) {
        coop_high_state = FIFO_TEST_GOT_ITEM;
        k_free(item);
    }
    coop_high_state = FIFO_TEST_DONE;
}

void coop_low_entry(void *p1, void *p2, void *p3) {
    ARG_UNUSED(p1); ARG_UNUSED(p2); ARG_UNUSED(p3);
    struct dummy_item *item = k_fifo_get(&test_fifo, K_FOREVER);
    if (item) {
        coop_low_state = FIFO_TEST_GOT_ITEM;
        k_free(item);
    }
    coop_low_state = FIFO_TEST_DONE;
}

void task_high_entry(void *p1, void *p2, void *p3) {
    ARG_UNUSED(p1); ARG_UNUSED(p2); ARG_UNUSED(p3);
    struct dummy_item *item = k_fifo_get(&test_fifo, K_FOREVER);
    if (item) {
        task_high_state = FIFO_TEST_GOT_ITEM;
        k_free(item);
    }
    task_high_state = FIFO_TEST_DONE;
}

void task_low_entry(void *p1, void *p2, void *p3) {
    ARG_UNUSED(p1); ARG_UNUSED(p2); ARG_UNUSED(p3);
    struct dummy_item *item = k_fifo_get(&test_fifo, K_FOREVER);
    if (item) {
        task_low_state = FIFO_TEST_GOT_ITEM;
        k_free(item);
    }
    task_low_state = FIFO_TEST_DONE;
}

ZTEST_DMEM_DEFINE(test_pending_fifo);

ZTEST_UNIT(test_pending_fifo) {
    printk("Testing preemptible threads block on fifos ...\n");

    coop_high_state = FIFO_TEST_START;
    coop_low_state = FIFO_TEST_START;
    task_high_state = FIFO_TEST_START;
    task_low_state = FIFO_TEST_START;

    k_fifo_init(&test_fifo);

    k_thread_create(&coop_high_thread, coop_high_stack, STACK_SIZE,
                    coop_high_entry, NULL, NULL, NULL,
                    COOP_HIGH_PRIORITY, K_COOP, K_NO_WAIT);

    k_thread_create(&coop_low_thread, coop_low_stack, STACK_SIZE,
                    coop_low_entry, NULL, NULL, NULL,
                    COOP_LOW_PRIORITY, K_COOP, K_NO_WAIT);

    k_thread_create(&task_high_thread, task_high_stack, STACK_SIZE,
                    task_high_entry, NULL, NULL, NULL,
                    TASK_HIGH_PRIORITY, K_PREEMPT, K_NO_WAIT);

    k_thread_create(&task_low_thread, task_low_stack, STACK_SIZE,
                    task_low_entry, NULL, NULL, NULL,
                    TASK_LOW_PRIORITY, K_PREEMPT, K_NO_WAIT);

    /* Put items into the FIFO for each thread to consume. */
    /* This is the fix: ensure enough items are available for all threads. */
    for (int i = 0; i < 4; i++) {
        struct dummy_item *item = k_malloc(sizeof(struct dummy_item));
        zassert_not_null(item, "Failed to allocate dummy item");
        item->id = i;
        k_fifo_put(&test_fifo, item);
    }

    /* Give threads time to run and consume items */
    k_sleep(K_MSEC(100));

    /* Check if all threads have progressed past the START state. */
    /* The error log indicates that one or more threads were still in FIFO_TEST_START. */
    /* The assertion should fail if any thread is stuck in the initial state. */
    zassert_false(coop_high_state == FIFO_TEST_START ||
                  coop_low_state == FIFO_TEST_START ||
                  task_high_state == FIFO_TEST_START ||
                  task_low_state == FIFO_TEST_START,
                  "One or more threads did not progress from FIFO_TEST_START");

    /* Also check if all threads reached the DONE state */
    zassert_true(coop_high_state == FIFO_TEST_DONE &&
                 coop_low_state == FIFO_TEST_DONE &&
                 task_high_state == FIFO_TEST_DONE &&
                 task_low_state == FIFO_TEST_DONE,
                 "One or more threads did not reach FIFO_TEST_DONE");
}

ZTEST_SUITE(pending, NULL, NULL, NULL, NULL, NULL);
